UPDATE institution_agents AS a SET university_id=f.university_id,faculty_id=f.id FROM faculties AS f JOIN universities AS un ON un.id=f.university_id JOIN institutions AS i ON i.university_id=un.id WHERE a.department='student_affairs' AND a.institution_id=i.id AND un.id='demo-university' AND un.name='جامعة قنا الأهلية' AND f.id='demo-computing' AND f.name='كلية الحاسبات والذكاء الاصطناعي' AND f.active=true AND a.organization_id IS NULL;
